import json, statistics

def grade(case, trace):
    calls = [s["tool"] for s in trace["steps"] if s.get("tool")]
    return {
        "outcome": trace["final_state"] == case["expected_state"],
        "no_forbidden": not set(calls) & set(case["forbidden_tools"]),
        "within_budget": len(trace["steps"]) <= case["max_steps"],
    }

def run_suite(cases, run_agent, trials=3):
    report = {}
    for case in cases:
        passes = [all(grade(case, run_agent(case["input"])).values())
                  for _ in range(trials)]
        report[case["id"]] = statistics.mean(passes)
    return report

print(json.dumps(run_suite([], lambda x: {}), indent=2))
